12	
13	// TestRunIngestCorruptTextIsWholeLineFailure 覆盖端到端语义：
14	// 损坏行只产出一条带原始行号、无 index/conflict 的 error；此前数据保留，
15	// 后续写入与查询照常；损坏查询不返回替换后的匹配；进程非零退出。
16	func TestRunIngestCorruptTextIsWholeLineFailure(t *testing.T) {
17		input := io.MultiReader(
18			// 行 1：先成功写入一个真实的 cpu 序列与一个显式 U+FFFD 序列。
19			strings.NewReader(`[{"name":"cpu","timestamp":1000,"value":0.5,"labels":{"host":"a"}}]`+"\n"),
20			strings.NewReader(`[{"name":"m�","timestamp":1,"value":7}]`+"\n"),
21			// 行 3：非法 UTF-8 字节的写入，整行失败。
22			bytes.NewReader(append(append([]byte(nil), rawBadUTF8Write...), '\n')),
23			// 行 4：孤立代理项转义的写入，整行失败，且不得与 U+FFFD 序列合并。
24			strings.NewReader(`[{"name":"m\uD800","timestamp":1,"value":9}]`+"\n"),
25			// 行 5：孤立代理项转义的查询，失败，不得经替换命中真实 U+FFFD 序列。
26			strings.NewReader(`{"op":"query","name":"m\uD800","start":0,"end":10}`+"\n"),
27			// 行 6：非法字节查询，失败。
28			bytes.NewReader([]byte(`{"op":"query","name":"cpu`+"\xff"+`","start":0,"end":10}`+"\n")),
29			// 行 7：合法查询此前数据，仍应正常得到行 1 的点。
30			strings.NewReader(`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`+"\n"),
31			// 行 8：合法补充平面写入，确认后续输入按序处理且行为不变。
32			strings.NewReader(`[{"name":"😀","timestamp":1,"value":1}]`+"\n"),
33		)
34	
35		var out bytes.Buffer
36		if code := runIngest(input, &out); code == 0 {
37			t.Fatalf("exit code = 0, want non-zero because corrupt lines failed")
38		}
39	
40		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
41		if len(lines) != 8 {
42			t.Fatalf("got %d output lines, want 8 (3 writes ok, 4 errors, 1 query ok): %v", len(lines), lines)
43		}
44	
45		// 行 1、行 2 成功。
46		if m := decodeResultLine(t, lines[0]); m["status"] != "ok" {
47			t.Fatalf("line 1 = %v, want ok", m)
48		}
49		if m := decodeResultLine(t, lines[1]); m["status"] != "ok" {
50			t.Fatalf("line 2 = %v, want ok", m)
51		}
52	
53		// 错误行：行号 3-6 全部为整行错误，无 index、无 conflict，原因可区分两类。
54		wantErr := []struct {
55			line   int
56			substr string
57		}{
58			{3, "UTF-8"},
59			{4, "surrogate"},
60			{5, "surrogate"},
61			{6, "UTF-8"},
62		}
63		for i, w := range wantErr {
64			m := decodeResultLine(t, lines[2+i])
65			if m["status"] != "error" || int(m["line"].(float64)) != w.line {
66				t.Fatalf("output %d = %v, want error on input line %d", i+2, m, w.line)
67			}
68			if _, has := m["index"]; has {
69				t.Fatalf("line %d error must not carry index: %v", w.line, m)
70			}
71			if _, has := m["conflict"]; has {
72				t.Fatalf("line %d error must not carry conflict: %v", w.line, m)
73			}
74			msg, _ := m["error"].(string)
75			if !strings.Contains(msg, w.substr) {
76				t.Fatalf("line %d error = %q, want substring %q", w.line, msg, w.substr)
77			}
78		}
79	
80		// 行 7：此前提交的数据仍可查询，只有行 1 的一个点（平均 0.5）。
81		q := decodeResultLine(t, lines[6])
82		if q["status"] != "ok" || q["op"] != "query" {
83			t.Fatalf("line 7 = %v, want ok query after corrupt lines", q)
84		}
85		series := q["series"].([]interface{})
86		if len(series) != 1 {
87			t.Fatalf("line 7 series = %v, want exactly the earlier cpu point", series)
88		}
89		s0 := series[0].(map[string]interface{})
90		if s0["count"].(float64) != 1 || s0["average"].(float64) != 0.5 {
91			t.Fatalf("line 7 series[0] = %v, want count=1 average=0.5", s0)
92		}
93	
94		// 行 8：合法补充平面写入仍被正常处理。
95		if m := decodeResultLine(t, lines[7]); m["status"] != "ok" {
96			t.Fatalf("line 8 = %v, want ok supplementary-plane write after failures", m)
97		}
98	}
99	
100	// TestRunIngestCorruptLineDoesNotCommitValidPrefix 即使数组前面的点完全合法，
101	// 含损坏文本的整行也不得提交任何点；命令非零退出，且后续空批快照不含该序列。
102	func TestRunIngestCorruptLineDoesNotCommitValidPrefix(t *testing.T) {
103		input := strings.Join([]string{
104			`[{"name":"old","timestamp":1,"value":9}]`,
105			`[{"name":"brandnew","timestamp":1,"value":1},{"name":"bad\uD800","timestamp":2,"value":2}]`,
106			`[]`,
107		}, "\n")
108		var out bytes.Buffer
109		if code := runIngest(strings.NewReader(input), &out); code == 0 {
110			t.Fatalf("exit code = 0, want non-zero")
111		}
112		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
113		if len(lines) != 3 {
114			t.Fatalf("got %d lines, want 3: %v", len(lines), lines)
115		}
116		mid := decodeResultLine(t, lines[1])
117		if mid["status"] != "error" || int(mid["line"].(float64)) != 2 {
118			t.Fatalf("line 2 = %v, want error on line 2", mid)
119		}
120		if _, has := mid["index"]; has {
121			t.Fatalf("corrupt line must fail as a whole, no index: %v", mid)
122		}
123		snap := decodeResultLine(t, lines[2])
124		gotSeries := snap["series"].([]interface{})
125		if len(gotSeries) != 1 {
126			t.Fatalf("snapshot = %v, want only old series, no brandnew commit", gotSeries)
127		}
128		name := gotSeries[0].(map[string]interface{})["name"].(string)
129		if name != "old" {
130			t.Fatalf("committed series name = %q, want old", name)
131		}
132	}
