52	// overlongLine 返回一段“合法 JSON 前缀 + 空白填充”的超长行内容，
53	// 总长为 maxIngestLineBytes+delta，且不含换行。前缀里的采样点绝不能被写入。
54	func overlongLine(delta int) io.Reader {
55		prefix := `[{"name":"cpu","timestamp":2000,"value":9},`
56		return io.MultiReader(
57			strings.NewReader(prefix),
58			&repeatReader{b: ' ', n: maxIngestLineBytes + delta - len(prefix)},
59		)
60	}
